#!/usr/bin/env bash
# Instructeurs et cours ; plus de dépôt de formulaire papier.
# - Fiche d'un instructeur (groupe Instructeurs) : « Cours donnés » (cocher = instructeur attitré, la ligne dit
#   qui il remplace ; décoché, le cours revient à l'instructeur de sa discipline), puis « Autres cours suivis »,
#   gratuitement, sans être élève ; un cours qu'il donne ne se « suit » pas. Même chose à la création ;
# - droit à l'image : plus de « Déposer un formulaire signé » sur la fiche (procédures createUpload/register
#   retirées) ; les anciens formulaires papier restent consultables ;
# - doc (droit à l'image, envois : « Six portes »), guides admin, glossaire, e2e. Pas de migration.
# Prérequis : apply-droit-image-vierge-consultation.sh.
# Usage (racine du repo) : bash apply-instructeurs-cours-sans-depot.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"packages/backend/src/modules/users/router.ts" 2>/dev/null | grep -qF "setTaughtCourses"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "readOnly" "apps/web/src/features/image-consent/FilePreviewPanel.tsx" 2>/dev/null || { echo "lancez d'abord apply-droit-image-vierge-consultation.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/admin/creer-un-utilisateur.mdx" "apps/web/content/docs/admin/gerer-un-membre.mdx" "apps/web/content/docs/dev/corbeille/les-versions-d-un-fichier.mdx" "apps/web/content/docs/dev/envois/les-photos-d-iphone.mdx" "apps/web/content/docs/dev/envois/sept-portes-trois-familles.mdx" "apps/web/content/docs/dev/envois/un-fichier-un-usage.mdx" "apps/web/content/docs/dev/index.mdx" "apps/web/content/docs/dev/legal/droit-a-l-image.mdx" "apps/web/content/docs/dev/qualite/tester-de-bout-en-bout.mdx" "apps/web/src/app/(admin)/dashboard/users/[id]/page.tsx" "apps/web/src/app/(admin)/dashboard/users/create/page.tsx" "apps/web/src/features/admin/users/components/ImageConsentForms.tsx" "apps/web/src/features/admin/users/courses/CoursesControl.tsx" "apps/web/src/features/admin/users/courses/CoursesPicker.tsx" "apps/web/src/features/admin/users/forms/CreateUserForm.tsx" "apps/web/src/features/docs/entities/procedureMap.generated.json" "apps/web/src/features/docs/glossary/glossary.admin.json" "e2e/creation-compte.spec.ts" "e2e/droit-a-l-image.spec.ts" "e2e/inscriptions-cours.spec.ts" "packages/backend/src/modules/courses/router.ts" "packages/backend/src/modules/imageConsent/imageConsentForm.service.ts" "packages/backend/src/modules/imageConsent/router.ts" "packages/backend/src/modules/users/router.ts" "packages/contracts/src/courses/enrollment.ts" "packages/contracts/src/legal/imageConsent.ts")
CREATED=("apps/web/src/features/admin/users/courses/TaughtCoursesPicker.tsx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "setTaughtCourses" "packages/backend/src/modules/users/router.ts" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

mkdir -p "apps/web/src/features/admin/users/courses"
